import React from "react";
import { useNavigate } from "react-router-dom";

export default function StudentDashboard() {
  const navigate = useNavigate();

  const actions = [
    { title: "View Candidates", desc: "Browse the list of approved candidates and their positions.", path: "/candidates" },
    { title: "Cast Vote", desc: "Securely cast your vote using OTP verification.", path: "/cast-vote" },
    { title: "Register Candidacy", desc: "Submit your requirements to apply as a candidate.", path: "/register-candidacy" },
    { title: "Election Results", desc: "View real-time turnout and final election results.", path: "/results" },
    { title: "Profile & Security", desc: "Manage your account details and two-factor authentication.", path: "/profile" },
  ];

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f7f9fc", padding: "50px" }}>
      <div style={{ maxWidth: "1100px", margin: "0 auto" }}>
        <header style={{ marginBottom: "40px", textAlign: "center" }}>
          <h1 style={{ fontSize: "2.2rem", color: "#1a1a1a", marginBottom: "10px" }}>
            Student Dashboard
          </h1>
          <p style={{ fontSize: "1rem", color: "#666" }}>
            Access your election tools and account features
          </p>
        </header>

        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
          gap: "25px"
        }}>
          {actions.map((a, i) => (
            <div
              key={i}
              onClick={() => navigate(a.path)}
              style={{
                padding: "25px",
                borderRadius: "12px",
                border: "1px solid #e0e6ed",
                background: "#fff",
                boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
                cursor: "pointer",
                transition: "all 0.2s ease-in-out"
              }}
              onMouseEnter={(e) => e.currentTarget.style.boxShadow = "0 4px 12px rgba(0,0,0,0.1)"}
              onMouseLeave={(e) => e.currentTarget.style.boxShadow = "0 2px 6px rgba(0,0,0,0.05)"}
            >
              <h2 style={{ fontSize: "1.25rem", color: "#007bff", marginBottom: "10px" }}>
                {a.title}
              </h2>
              <p style={{ fontSize: "0.95rem", color: "#555", lineHeight: "1.5" }}>
                {a.desc}
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
